import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"对话与会话","description":"","frontmatter":{"title":"对话与会话"},"headers":[],"relativePath":"zh/guide/agent-workspace.md","filePath":"zh/guide/agent-workspace.md"}'),i={name:"zh/guide/agent-workspace.md"};function o(n,a,s,h,d,c){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="对话与会话" tabindex="-1">对话与会话 <a class="header-anchor" href="#对话与会话" aria-label="Permalink to &quot;对话与会话&quot;">​</a></h1><p>Agent 工作台用于执行需要模型推理和工具协作的开放式任务。Agent 会根据目标、上下文和工具结果动态规划并调整下一步，也可将工作流作为工具调用；工作流模式按预定义的节点、连线与分支规则组织可重复、受控的执行路径。顶部模式切换不会改变已有数据。</p><h2 id="开始对话" tabindex="-1">开始对话 <a class="header-anchor" href="#开始对话" aria-label="Permalink to &quot;开始对话&quot;">​</a></h2><ol><li>在 Agent 列表中选择已有 Agent，或按<a href="./agents.html">创建 Agent</a>新建一个。</li><li>选择<strong>开始对话</strong>，输入目标、所需输入和期望输出。</li><li>等待回答完成，检查工具卡片与结果，再发送后续指令。</li></ol><p>模型未配置时，对话页会提供配置提示。先完成模型设置，不要把配置提示误当作 Agent 已可运行。</p><h2 id="管理会话" tabindex="-1">管理会话 <a class="header-anchor" href="#管理会话" aria-label="Permalink to &quot;管理会话&quot;">​</a></h2><p>左侧会话列表支持检索、置顶、归档和删除等入口，实际可用操作以当前角色和界面为准。</p><ul><li><strong>会话</strong>保存任务上下文，可在 Agent 会话或链路入口继续查看。</li><li><strong>归档</strong>用于收起暂不活跃的会话，不等于删除。</li><li><strong>删除</strong>影响本地会话记录，操作前确认不再需要其中的上下文。</li><li><strong>清空／编辑消息</strong>可能改变后续上下文；重新执行前检查输入与授权。</li></ul><h2 id="查看执行链路" tabindex="-1">查看执行链路 <a class="header-anchor" href="#查看执行链路" aria-label="Permalink to &quot;查看执行链路&quot;">​</a></h2><p>从对应会话进入链路，查看任务、子任务、工具调用与相关节点。定时任务有独立运行记录，可从任务行打开最近会话。</p><p>链路中的请求响应可能含业务内容，导出或分享前必须脱敏。日志中的错误不等于工具已经成功完成业务操作，应同时检查工具结果。</p><h2 id="任务成功判断" tabindex="-1">任务成功判断 <a class="header-anchor" href="#任务成功判断" aria-label="Permalink to &quot;任务成功判断&quot;">​</a></h2><ul><li>回答与请求的目标、输入和输出一致。</li><li>工具卡片没有未处理的鉴权、网络或权限错误。</li><li>需要修改文件、调用外部服务或运行流程时，另行验证实际结果。</li><li>对开放式任务继续明确约束；不要把模型描述当作执行凭证。</li></ul><p>下一步：<a href="./skills.html">选择技能与 MCP</a> · <a href="./schedules.html">创建定时任务</a></p>',14)])])}const u=e(i,[["render",o]]);export{g as __pageData,u as default};
